/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `notices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `body` text NOT NULL,
  `audience` enum('All','Branch','Department') NOT NULL DEFAULT 'All',
  `branch_id` int(11) DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `priority` enum('Normal','Important','Urgent') NOT NULL DEFAULT 'Normal',
  `publish_date` date NOT NULL,
  `expire_date` date DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `status` enum('Draft','Published','Archived') NOT NULL DEFAULT 'Published',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `notices` DISABLE KEYS */;
INSERT INTO `notices` VALUES
(1,'Welcome to the HR & Payroll portal','Use this portal to apply for leave, view payslips and manage your profile. Contact HR for any help.','All',NULL,NULL,'Normal','2026-10-12',NULL,NULL,'Published','2026-10-12 03:06:43'),
(2,'Eid holidays and salary schedule','The office will remain closed during Eid holidays. Salary and festival bonus will be paid before the holidays begin.','All',NULL,NULL,'Important','2026-10-12',NULL,NULL,'Published','2026-10-12 03:06:45'),
(3,'IT department: system maintenance','Servers will be under maintenance on Friday night. Please save your work.','Department',NULL,3,'Normal','2026-10-12',NULL,NULL,'Published','2026-10-12 03:06:45');
/*!40000 ALTER TABLE `notices` ENABLE KEYS */;
DROP TABLE IF EXISTS `opening_balances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
